367	  async function assertCanCreateAgentsForCompany(req: Request, companyId: string) {
368	    assertCompanyAccess(req, companyId);
369	    if (req.actor.type === "board") {
370	      if (req.actor.source === "local_implicit" || req.actor.isInstanceAdmin) return null;
371	      const allowed = await access.canUser(companyId, req.actor.userId, "agents:create");
372	      if (!allowed) {
373	        throw forbidden("Missing permission: agents:create");
374	      }
375	      return null;
376	    }
377	    if (!req.actor.agentId) throw forbidden("Agent authentication required");
378	    const actorAgent = await svc.getById(req.actor.agentId);
379	    if (!actorAgent || actorAgent.companyId !== companyId) {
380	      throw forbidden("Agent key cannot access another company");
381	    }
382	    const allowedByGrant = await access.hasPermission(companyId, "agent", actorAgent.id, "agents:create");
383	    if (!allowedByGrant && !canCreateAgents(actorAgent)) {
384	      throw forbidden("Missing permission: can create agents");
385	    }
386	    return actorAgent;
387	  }
