429	  async function buildSkippedWakeupResponse(
430	    agent: NonNullable<Awaited<ReturnType<typeof svc.getById>>>,
431	    payload: Record<string, unknown> | null | undefined,
432	  ) {
433	    const issueId = typeof payload?.issueId === "string" && payload.issueId.trim() ? payload.issueId : null;
434	    if (!issueId) {
435	      return {
436	        status: "skipped" as const,
437	        reason: "wakeup_skipped",
438	        message: "Wakeup was skipped.",
439	        issueId: null,
440	        executionRunId: null,
441	        executionAgentId: null,
442	        executionAgentName: null,
443	      };
444	    }
445	
446	    const issue = await db
447	      .select({
448	        id: issuesTable.id,
449	        executionRunId: issuesTable.executionRunId,
450	      })
451	      .from(issuesTable)
452	      .where(and(eq(issuesTable.id, issueId), eq(issuesTable.companyId, agent.companyId)))
453	      .then((rows) => rows[0] ?? null);
454	
455	    if (!issue?.executionRunId) {
456	      return {
457	        status: "skipped" as const,
458	        reason: "wakeup_skipped",
459	        message: "Wakeup was skipped.",
460	        issueId,
461	        executionRunId: null,
462	        executionAgentId: null,
463	        executionAgentName: null,
464	      };
465	    }
466	
467	    const executionRun = await heartbeat.getRun(issue.executionRunId);
468	    if (!executionRun || (executionRun.status !== "queued" && executionRun.status !== "running")) {
469	      return {
470	        status: "skipped" as const,
471	        reason: "wakeup_skipped",
472	        message: "Wakeup was skipped.",
473	        issueId,
474	        executionRunId: issue.executionRunId,
475	        executionAgentId: null,
476	        executionAgentName: null,
477	      };
478	    }
479	
480	    const executionAgent = await svc.getById(executionRun.agentId);
481	    const executionAgentName = executionAgent?.name ?? null;
482	
483	    return {
484	      status: "skipped" as const,
485	      reason: "issue_execution_deferred",
486	      message: executionAgentName
487	        ? `Wakeup was deferred because this issue is already being executed by ${executionAgentName}.`
488	        : "Wakeup was deferred because this issue already has an active execution run.",
489	      issueId,
490	      executionRunId: executionRun.id,
491	      executionAgentId: executionRun.agentId,
492	      executionAgentName,
493	    };
494	  }
