496	  async function assertCanUpdateAgent(req: Request, targetAgent: { id: string; companyId: string }) {
497	    assertCompanyAccess(req, targetAgent.companyId);
498	    if (req.actor.type === "board") {
499	      await assertBoardCanManageAgentsForCompany(req, targetAgent.companyId);
500	      return;
501	    }
502	    if (!req.actor.agentId) throw forbidden("Agent authentication required");
503	
504	    const actorAgent = await svc.getById(req.actor.agentId);
505	    if (!actorAgent || actorAgent.companyId !== targetAgent.companyId) {
506	      throw forbidden("Agent key cannot access another company");
507	    }
508	
509	    if (actorAgent.id === targetAgent.id) return;
510	    if (actorAgent.role === "ceo") return;
511	    const allowedByGrant = await access.hasPermission(
512	      targetAgent.companyId,
513	      "agent",
514	      actorAgent.id,
515	      "agents:create",
516	    );
517	    if (allowedByGrant || canCreateAgents(actorAgent)) return;
518	    throw forbidden("Only CEO or agent creators can modify other agents");
519	  }
